import { Bcgetuser } from "@/app/actions/bcuser";

export default async function Userlist() {
  const res = await Bcgetuser();

  if (!res.success || !res.data) {
    return <p className="p-4 text-gray-500">No users found.</p>;
  }

  // 1. CRITICAL: Convert to plain JSON to strip hidden functions/methods
  // This prevents the "Functions are not valid as a child" error
  const cleanUsers = JSON.parse(JSON.stringify(res.data));

  return (
    <div className="flex flex-col gap-2 p-4 border border-dashed border-orange-200 rounded-xl bg-orange-50/30">
      <h2 className="text-xs font-bold text-orange-600 uppercase tracking-widest mb-2">
        Live User Stream
      </h2>

      {cleanUsers.map((ele: any) => (
        <div key={ele._id?.toString()} className="flex items-center gap-3 py-1">
          <div className="h-2 w-2 rounded-full bg-green-500 animate-spin" />
          <span className="font-medium text-slate-700">{ele.name}</span>
          <span className="text-xs text-slate-400">ID: {ele.userId}</span>
        </div>
      ))}
    </div>
  );
}
